#include <verilated_vcd_c.h>
#include <iostream>
#include <fstream>
#include <vector>
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <verilated.h>
#include "Vtb_zfp_top.h" // Generated by Verilator
#include <iomanip>

vluint64_t main_time = 0; // Simulation time tracker

// Called by $time in Verilog
double sc_time_stamp() {
    return main_time;
}

void toggle_clock(Vtb_zfp_top* top, VerilatedVcdC* tfp) {
    top->clk = 1;
    top->eval();
    if (tfp) tfp->dump(main_time);
    main_time += 5;
    top->clk = 0;
    top->eval();
    if (tfp) tfp->dump(main_time);  
    main_time += 5;
}

int main(int argc, char** argv) {
    Verilated::commandArgs(argc, argv);
    Vtb_zfp_top* top = new Vtb_zfp_top;
    Verilated::traceEverOn(true);
    VerilatedVcdC* tfp = new VerilatedVcdC;
    top->trace(tfp, 99);  // Trace 99 levels of hierarchy
    tfp->open("sim_trace.vcd");

    // --- Configuration ---
    const size_t HEADER_SIZE = 48; 
    const size_t BUS_WIDTH_BYTES = 64; // 512-bit datapath
    const char* IN_FILE = "noisy_float.bin"; // Change to your binary data file
    const char* OUT_FILE = "axi_test_output.bin";
    const char* GOLDEN_FILE = "zfp_golden.bin";
    const char* MONITOR_FILE = "golden_monitor.bin";
    const uint8_t comp_mode = 0b11111110;

    // --- tuser Configuration (Corundum convention) ---
    // Adjust TUSER_MASK to match your AXIS_SYNC_TX_USER_WIDTH (e.g., 17 bits -> 0x1FFFFULL)
    const uint64_t TUSER_MASK        = 0x1FFFFULL;
    const uint64_t TUSER_META_MASK   = TUSER_MASK & ~1ULL; // Bits [N-1:1] = packet metadata
    // Example using asymmetric bit patterns (catches bit-reversal and off-by-1 shift bugs)
    const uint64_t EXPECTED_META     = (0xB3C5ULL << 1) & TUSER_META_MASK; // 1011_0011_1100_0101
    const uint64_t JUNK_MID_PKT_META = (0x1E49ULL << 1) & TUSER_META_MASK; // 0001_1110_0100_1001
    const bool     INJECT_BAD_FRAME  = true; // Set true to test tuser[0] bad_frame latching on tlast
    const size_t   BAD_FRAME_BEAT    = 2;     // Beat index to assert tuser[0] when enabled

    // 1. Generate Header and Load Payload
    std::vector<uint8_t> tx_packet;
    
    // Dummy 48-byte UDP/IP/Ethernet + custom header
    for (size_t i = 0; i < HEADER_SIZE; i++) {
        if (i != 44) {
            tx_packet.push_back((uint8_t)(i & 0xFF));
        } else {
            tx_packet.push_back(comp_mode);
        }
    }

    // Load 32-bit floating point data from binary file
    std::ifstream infile(IN_FILE, std::ios::binary);
    if (!infile.is_open()) {
        std::cerr << "Warning: Could not open " << IN_FILE << ". Using dummy payload." << std::endl;
        for (int i = 0; i < 256; i++) tx_packet.push_back((uint8_t)(i % 256));
    } else {
        infile.seekg(0, std::ios::end);
        size_t file_size = infile.tellg();
        infile.seekg(0, std::ios::beg);
        
        std::vector<uint8_t> payload(file_size);
        infile.read(reinterpret_cast<char*>(payload.data()), file_size);
        infile.close();

        // Append payload to packet
        tx_packet.insert(tx_packet.end(), payload.begin(), payload.end());
        std::cout << "Loaded packet. Total size: " << tx_packet.size() << " bytes." << std::endl;
    }

    // 2. Initialize Inputs
    top->clk = 0;
    top->rst = 1;
    top->s_tx_tvalid = 0;
    top->s_tx_tlast = 0;
    top->s_tx_tkeep = 0;
    top->s_tx_tuser = 0;
    for (int i = 0; i < 16; i++) top->s_tx_tdata[i] = 0;
    top->m_rx_tready = 1; // Always ready to receive in this testbench

    // 3. Reset Sequence
    std::cout << "Applying Reset..." << std::endl;
    for (int i = 0; i < 5; i++) toggle_clock(top, tfp);
    top->rst = 0;
    for (int i = 0; i < 5; i++) toggle_clock(top, tfp);

    // 4. Drive AXI Stream Data & Capture RX
    std::cout << "Injecting Data and Monitoring RX..." << std::endl;

    size_t tx_offset = 0;
    size_t tx_beat_idx = 0;
    size_t mon_beat_idx = 0;
    size_t rx_beat_idx = 0;

    std::vector<uint8_t> rx_packet;
    std::vector<uint8_t> mon_packet; // Compressor monitor
    bool tx_done = false;
    bool rx_done = false;
    bool mon_done = false;
    bool mon_tuser_pass = true;
    bool rx_tuser_pass = true;

    // Loop until reception is complete, with timeout
    while ((!rx_done) && main_time < 1500000) { 
        
        // --- TX Logic Setup ---
        if (!tx_done) {
            top->s_tx_tvalid = 1;
            
            size_t remaining = tx_packet.size() - tx_offset;
            size_t chunk_size = std::min(remaining, BUS_WIDTH_BYTES);
            
            // Copy bytes into the 512-bit (16x 32-bit) tdata array
            uint32_t tdata_temp[16] = {0};
            std::memcpy(tdata_temp, &tx_packet[tx_offset], chunk_size);
            for (int i = 0; i < 16; i++) {
                top->s_tx_tdata[i] = tdata_temp[i];
            }

            // Setup tkeep and tlast
            uint64_t tkeep = 0;
            for (size_t i = 0; i < chunk_size; i++) {
                tkeep |= (1ULL << i);
            }
            top->s_tx_tkeep = tkeep;
            top->s_tx_tlast = (remaining <= BUS_WIDTH_BYTES) ? 1 : 0;

            // Drive Corundum tuser: valid metadata on beat 0, junk on subsequent beats, optional bad_frame
            uint64_t tx_meta = (tx_beat_idx == 0) ? EXPECTED_META : JUNK_MID_PKT_META;
            uint64_t tx_bad  = (INJECT_BAD_FRAME && (tx_beat_idx == BAD_FRAME_BEAT)) ? 1ULL : 0ULL;
            top->s_tx_tuser  = (tx_meta | tx_bad) & TUSER_MASK;
        } else {
            top->s_tx_tvalid = 0;
            top->s_tx_tlast = 0;
            top->s_tx_tkeep = 0;
            top->s_tx_tuser = 0;
        }

        // Let combinational logic settle
        top->eval();

        // Evaluate handshakes
        bool tx_fire  = top->s_tx_tvalid && top->s_tx_tready;
        bool rx_fire  = top->m_rx_tvalid && top->m_rx_tready;
        bool mon_fire = top->mon_tvalid  && top->mon_tready;
        
        // --- RX Logic Capture (Decompressor Output) ---
        if (rx_fire) {
            uint32_t rx_data[16];
            for (int i = 0; i < 16; i++) {
                rx_data[i] = top->m_rx_tdata[i];
            }
            
            uint8_t* rx_bytes = reinterpret_cast<uint8_t*>(rx_data);
            uint64_t rx_keep = top->m_rx_tkeep;
            
            // Capture valid bytes based on tkeep
            for (int i = 0; i < BUS_WIDTH_BYTES; i++) {
                if ((rx_keep >> i) & 1) {
                    rx_packet.push_back(rx_bytes[i]);
                }
            }

            // Verify RX tuser
            uint64_t rx_u = static_cast<uint64_t>(top->m_rx_tuser) & TUSER_MASK;
            if ((rx_u & TUSER_META_MASK) != EXPECTED_META) {
                std::cerr << "FAIL: m_rx_tuser metadata mismatch on beat " << rx_beat_idx
                          << ". Expected: 0x" << std::hex << EXPECTED_META
                          << ", Got: 0x" << (rx_u & TUSER_META_MASK) << std::dec << std::endl;
                rx_tuser_pass = false;
            }
            
            if (top->m_rx_tlast) {
                uint64_t expected_bad = INJECT_BAD_FRAME ? 1ULL : 0ULL;
                if ((rx_u & 1ULL) != expected_bad) {
                    std::cerr << "FAIL: m_rx_tuser[0] (bad_frame) mismatch on tlast. Expected: "
                              << expected_bad << ", Got: " << (rx_u & 1ULL) << std::endl;
                    rx_tuser_pass = false;
                }
                rx_done = true;
            }
            rx_beat_idx++;
        }

        // --- Mon Logic Capture (Compressor Output) ---
        if (mon_fire) {
            uint32_t mon_data[16];
            for (int i = 0; i < 16; i++) {
                mon_data[i] = top->mon_tdata[i];
            }
            
            uint8_t* mon_bytes = reinterpret_cast<uint8_t*>(mon_data);
            uint64_t mon_keep = top->mon_tkeep;
            
            // Capture valid bytes based on tkeep
            for (int i = 0; i < BUS_WIDTH_BYTES; i++) {
                if ((mon_keep >> i) & 1) {
                    mon_packet.push_back(mon_bytes[i]);
                }
            }

            // Verify Monitor tuser
            uint64_t mon_u = static_cast<uint64_t>(top->mon_tuser) & TUSER_MASK;
            if ((mon_u & TUSER_META_MASK) != EXPECTED_META) {
                std::cerr << "FAIL: mon_tuser metadata mismatch on beat " << mon_beat_idx
                          << ". Expected: 0x" << std::hex << EXPECTED_META
                          << ", Got: 0x" << (mon_u & TUSER_META_MASK) << std::dec << std::endl;
                mon_tuser_pass = false;
            }
            
            if (top->mon_tlast) {
                uint64_t expected_bad = INJECT_BAD_FRAME ? 1ULL : 0ULL;
                if ((mon_u & 1ULL) != expected_bad) {
                    std::cerr << "FAIL: mon_tuser[0] (bad_frame) mismatch on tlast. Expected: "
                              << expected_bad << ", Got: " << (mon_u & 1ULL) << std::endl;
                    mon_tuser_pass = false;
                }
                mon_done = true;
            }
            mon_beat_idx++;
        }

        // Capture state (Clock Edge)
        toggle_clock(top, tfp);

        // Advance pointers post-clock
        if (tx_fire && !tx_done) {
            tx_offset += BUS_WIDTH_BYTES;
            tx_beat_idx++;
            if (tx_offset >= tx_packet.size()) {
                tx_done = true;
            }
        }
    }

    // Flush pipeline
    for (int i = 0; i < 40; i++) toggle_clock(top, tfp);

    // Report tuser verification results
    std::cout << "Monitor tuser check: " << (mon_tuser_pass ? "PASS" : "FAIL") << std::endl;
    std::cout << "RX tuser check:      " << (rx_tuser_pass  ? "PASS" : "FAIL") << std::endl;

    // 5. Post-Process Monitored Data (Compressor Output)
    std::cout << "Captured " << mon_packet.size() << " bytes from compressor monitor." << std::endl;

    std::ifstream golden_mon_file(MONITOR_FILE, std::ios::binary);
    if (golden_mon_file.is_open()) {
        golden_mon_file.seekg(0, std::ios::end);
        size_t golden_mon_size = golden_mon_file.tellg();
        golden_mon_file.seekg(0, std::ios::beg);
        
        std::vector<uint8_t> golden_mon_payload(golden_mon_size);
        golden_mon_file.read(reinterpret_cast<char*>(golden_mon_payload.data()), golden_mon_size);
        golden_mon_file.close();

        std::cout << "\nStarting detailed Monitor comparison..." << std::endl;
        
        int incorrect_count = 0;
        bool mon_match = true;
        
        // Account for header in the total expected size
        size_t expected_total_size = golden_mon_size + HEADER_SIZE;
        size_t compare_size = std::min(mon_packet.size(), expected_total_size);
        size_t num_packets = (compare_size + 63) / 64;

        for (size_t i = 0; i < num_packets; i++) {
            bool packet_missmatch = false;
            
            for (size_t j = 0; j < 64; j++) {
                size_t idx = i * 64 + j;
                
                if (idx >= compare_size) break;

                if (idx < HEADER_SIZE) {
                    if (mon_packet[idx] != tx_packet[idx]) {
                        std::cerr << "FAIL: Monitor header mismatch at byte " << idx
                                  << ". Expected: 0x" << std::hex << (int)tx_packet[idx] 
                                  << ", Got: 0x" << (int)mon_packet[idx] << std::dec << std::endl;
                        packet_missmatch = true;
                        mon_match = false;
                        break;
                    }
                } else {
                    if (mon_packet[idx] != golden_mon_payload[idx - HEADER_SIZE]) {
                        std::cerr << "FAIL: Monitor data mismatch at byte " << idx
                                  << ". Expected (Golden): 0x" << std::hex << std::setw(2) << std::setfill('0') << (int)golden_mon_payload[idx - HEADER_SIZE] 
                                  << ", Got (RTL): 0x" << std::setw(2) << std::setfill('0') << (int)mon_packet[idx] << std::dec << std::endl;
                        packet_missmatch = true;                        
                        mon_match = false;
                        break;
                    }
                }
            }

            if (packet_missmatch) { 
                incorrect_count++;
                
                size_t start_idx = i * 64;
                size_t end_idx = std::min(start_idx + 64, compare_size);

                std::cout << "\n--- Packet " << i << " Mismatch: Expected ---" << std::endl;
                for (size_t k = start_idx; k < end_idx; k++) {
                    if (k < HEADER_SIZE) {
                        std::cout << "0x" << std::hex << std::setw(2) << std::setfill('0') << (int)tx_packet[k] << " ";
                    } else {
                        std::cout << "0x" << std::hex << std::setw(2) << std::setfill('0') << (int)golden_mon_payload[k - HEADER_SIZE] << " ";
                    }
                }
                std::cout << std::dec << "\n" << std::endl;

                std::cout << "--- Packet " << i << " Mismatch: Got (RTL) ---" << std::endl;
                for (size_t k = start_idx; k < end_idx; k++) {
                    std::cout << "0x" << std::hex << std::setw(2) << std::setfill('0') << (int)mon_packet[k] << " ";
                }
                std::cout << std::dec << "\n" << std::endl;

                if (incorrect_count >= 2) {
                    std::cerr << "--- Reached 2 incorrect packets. Stopping monitor comparison. ---" << std::endl;
                    break;
                }
            }
        }
    
        if (mon_match) {
            if (mon_packet.size() != expected_total_size) {
                std::cerr << "WARNING: Monitor data perfectly matched, but total sizes differ! RTL Monitor: " 
                          << mon_packet.size() << " bytes, Expected: " << expected_total_size << " bytes." << std::endl;
            } else {
                std::cout << "SUCCESS: All Monitor data perfectly matches the Python golden model!" << std::endl;
            }
        }
    } else {
        std::cerr << "Error: Could not read " << MONITOR_FILE << std::endl;
    }

    // 6. Post-Process RX Data (Remove Header and Save)
    std::cout << "Simulation Complete. Captured " << rx_packet.size() << " bytes." << std::endl;

    if (rx_packet.size() > HEADER_SIZE) {
        size_t payload_size = rx_packet.size() - HEADER_SIZE;
        std::vector<uint8_t> rtl_payload(rx_packet.begin() + HEADER_SIZE, rx_packet.end());
        
        // Save RTL output
        std::ofstream outfile(OUT_FILE, std::ios::binary);
        outfile.write(reinterpret_cast<char*>(rtl_payload.data()), payload_size);
        outfile.close();

        // 7. Run Python Golden Model & Compare
        std::cout << "Running Python golden model..." << std::endl;
        std::string command = std::string("python3 zfp_golden.py --input ") + IN_FILE + " --output " + GOLDEN_FILE + " --monitor " + MONITOR_FILE;

        int py_status = std::system(command.c_str()); 
        
        if (py_status == 0) {
            std::ifstream golden_file(GOLDEN_FILE, std::ios::binary);
            if (golden_file.is_open()) {
                golden_file.seekg(0, std::ios::end);
                size_t golden_size = golden_file.tellg();
                golden_file.seekg(0, std::ios::beg);
                
                std::vector<uint8_t> golden_payload(golden_size);
                golden_file.read(reinterpret_cast<char*>(golden_payload.data()), golden_size);
                golden_file.close();

                if (payload_size != golden_size) {
                    std::cerr << "FAIL: Size mismatch! RTL: " << payload_size 
                              << " bytes, Golden: " << golden_size << " bytes." << std::endl;
                } else {
                    bool match = true;
                    for (size_t i = 0; i < payload_size; i++) {
                        if (rtl_payload[i] != golden_payload[i]) {
                            std::cerr << "FAIL: Data mismatch at byte " << i 
                                      << ". RTL: 0x" << std::hex << (int)rtl_payload[i] 
                                      << ", Golden: 0x" << (int)golden_payload[i] << std::dec << std::endl;
                            match = false;
                            break;
                        }
                    }
                    if (match) std::cout << "SUCCESS: RTL output matches Python golden model!" << std::endl;
                }
            } else {
                std::cerr << "Error: Could not read " << GOLDEN_FILE << std::endl;
            }
        } else {
            std::cerr << "Error: Python golden model execution failed." << std::endl;
        }
    } else {
        std::cerr << "Error: Received packet is too small." << std::endl;
    }

    top->final();
    if (tfp) {
        tfp->close();
        delete tfp;
    }
    delete top;
    return 0;
}